package com.medicine.reminder.controller;
import com.medicine.reminder.model.*; import com.medicine.reminder.repository.*; import com.medicine.reminder.service.HistoryService; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@RestController public class DashboardController {private final ProfileRepository profiles;private final ReminderRepository reminders;private final MedicineRepository medicines;private final HistoryService history;public DashboardController(ProfileRepository p,ReminderRepository r,MedicineRepository m,HistoryService h){profiles=p;reminders=r;medicines=m;history=h;}private Long uid(Authentication a){return(Long)a.getDetails();}
 @GetMapping("/api/dashboard") public Map<String,Object> dashboard(@RequestParam Long profileId,Authentication a){if(profiles.findByIdAndUserId(profileId,uid(a)).isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Profile not found");LocalDate today=LocalDate.now();String day=today.getDayOfWeek().name().substring(0,3);List<Map<String,Object>> due=reminders.findByMedicineProfileId(profileId).stream().filter(r->Boolean.TRUE.equals(r.getIsActive())).filter(r->inRange(r,today)).filter(r->!"WEEKLY".equals(r.getFrequency())||(r.getDaysOfWeek()!=null&&r.getDaysOfWeek().contains(day))).sorted(Comparator.comparing(Reminder::getTime)).map(r->view(r,history.today(r.getId()))).toList();List<Map<String,Object>> low=medicines.findByProfileId(profileId).stream().filter(m->m.getStock()!=null&&m.getStock()<=Optional.ofNullable(m.getLowStockThreshold()).orElse(5)).map(m->Map.<String,Object>of("id",m.getId(),"name",m.getName(),"stock",m.getStock(),"lowStockThreshold",Optional.ofNullable(m.getLowStockThreshold()).orElse(5))).toList();return Map.of("reminders",due,"lowStock",low,"streakDays",streak(profileId));}
 private boolean inRange(Reminder r,LocalDate d){return(r.getStartDate()==null||!d.isBefore(r.getStartDate()))&&(r.getEndDate()==null||!d.isAfter(r.getEndDate()));}private Map<String,Object> view(Reminder r,MedicineHistory h){Medicine m=r.getMedicine();Map<String,Object>x=new LinkedHashMap<>();x.put("id",r.getId());x.put("time",r.getTime());x.put("status",h==null?null:h.getStatus());x.put("medicineId",m.getId());x.put("medicine",m.getName());x.put("dosage",m.getDosage());x.put("color",m.getColor());x.put("stock",Optional.ofNullable(m.getStock()).orElse(0));x.put("lowStockThreshold",Optional.ofNullable(m.getLowStockThreshold()).orElse(5));x.put("isLowStock",Optional.ofNullable(m.getStock()).orElse(0)<=Optional.ofNullable(m.getLowStockThreshold()).orElse(5));return x;}private int streak(Long profileId){Map<LocalDate,List<MedicineHistory>>days=new HashMap<>();for(MedicineHistory h:history.list(profileId))days.computeIfAbsent(h.getTakenAt().toLocalDate(),k->new ArrayList<>()).add(h);int c=0;for(LocalDate d=LocalDate.now();;d=d.minusDays(1)){List<MedicineHistory>e=days.get(d);if(e==null||e.isEmpty()||e.stream().anyMatch(h->!"TAKEN".equals(h.getStatus())))break;c++;}return c;}}
